fn generate_svg(text: &str, settings: &Settings) -> String {
    let lines: Vec<&str> = text.lines().collect();
    let mut max_cols = 0;
    for line in &lines {
        max_cols = max_cols.max(line.chars().count());
    }
    let max_rows = lines.len();

    let svg_width = ((max_cols as f32 + 1.0) * 8.0 * settings.scale) as u32; // Simplified
    let svg_height = ((max_rows as f32 + 1.0) * 16.0 * settings.scale) as u32; // Simplified

    // Correcting SVG dimensions calculation based on observations
    let max_col_idx = if max_cols > 0 { max_cols - 1 } else { 0 };
    let max_row_idx = if max_rows > 0 { max_rows - 1 } else { 0 };
    let svg_width = ((max_col_idx as f32 + 2.0) * 8.0 * settings.scale) as u32;
    let svg_height = ((max_row_idx as f32 + 2.0) * 16.0 * settings.scale) as u32;

    let mut elements = String::new();

    // Add backdrop
    elements.push_str(&format!(r#"  <rect class="backdrop" x="0" y="0" width="{}" height="{}"></rect>
"#, svg_width, svg_height));

    // Simple character-by-character rendering for now
    for (row, line) in lines.iter().enumerate() {
        let chars: Vec<char> = line.chars().collect();
        let mut col = 0;
        while col < chars.len() {
            let c = chars[col];
            let x = (col as f32 * 8.0 + 4.0) * settings.scale;
            let y = (row as f32 * 16.0 + 8.0) * settings.scale;

            match c {
                '-' => {
                    let mut end_col = col;
                    while end_col + 1 < chars.len() && chars[end_col + 1] == '-' {
                        end_col += 1;
                    }
                    let x1 = (col as f32 * 8.0) * settings.scale;
                    let x2 = (end_col as f32 * 8.0 + 8.0) * settings.scale;
                    elements.push_str(&format!(r#"  <line x1="{}" y1="{}" x2="{}" y2="{}" class="solid"></line>
"#, x1, y, x2, y));
                    col = end_col + 1;
                    continue;
                }
                '|' => {
                    let y1 = (row as f32 * 16.0) * settings.scale;
                    let y2 = (row as f32 * 16.0 + 16.0) * settings.scale;
                    elements.push_str(&format!(r#"  <line x1="{}" y1="{}" x2="{}" y2="{}" class="solid"></line>
"#, x, y1, x, y2));
                }
                '+' => {
                    // Just a point for now? Or should it connect?
                    // Original Svgbob connects them.
                }
                _ if c.is_alphanumeric() || c == ' ' => {
                    let mut text_str = String::new();
                    let start_col = col;
                    while col < chars.len() && (chars[col].is_alphanumeric() || chars[col] == ' ') {
                        text_str.push(chars[col]);
                        col += 1;
                    }
                    if !text_str.trim().is_empty() {
                        let tx = (start_col as f32 * 8.0 + 2.0) * settings.scale;
                        let ty = (row as f32 * 16.0 + 12.0) * settings.scale;
                        elements.push_str(&format!(r#"  <text x="{}" y="{}" >{}</text>
"#, tx, ty, text_str));
                    }
                    continue;
                }
                _ => {}
            }
            col += 1;
        }
    }

    format!(r#"<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" class="svgbob">
  <style>.svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon {{
