        match args[i].as_str() {
            "--help" | "-h" => {
                print_help();
                return;
            }
            "--version" | "-V" => {
                println!("svgbob 0.7.6");
                return;
            }
            "--background" => {
                settings.background = args[i+1].clone();
                i += 2;
            }
            "--fill-color" => {
                settings.fill_color = args[i+1].clone();
                i += 2;
            }
            "--stroke-color" => {
