use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::path::Path;

struct Settings {
    background: String,
    fill_color: String,
    stroke_color: String,
    font_family: String,
    font_size: u32,
    stroke_width: f32,
    scale: f32,
    inline: bool,
    output: Option<String>,
    input: Option<String>,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() > 1 && args[1] == "build" {
        handle_build(&args[2..]);
        return;
    }
    if args.len() > 1 && args[1] == "help" {
        print_help();
        return;
    }

    let mut settings = Settings {
        background: "white".to_string(),
        fill_color: "black".to_string(),
        stroke_color: "black".to_string(),
        font_family: "Iosevka Fixed, monospace".to_string(),
        font_size: 14,
        stroke_width: 2.0,
        scale: 1.0,
        inline: false,
        output: None,
        input: None,
    };

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_help();
                return;
            }
            "--version" | "-V" => {
                println!("svgbob 0.7.6");
                return;
            }
            "--background" => {
                settings.background = args[i+1].clone();
                i += 2;
            }
            "--fill-color" => {
                settings.fill_color = args[i+1].clone();
                i += 2;
            }
            "--stroke-color" => {
                settings.stroke_color = args[i+1].clone();
                i += 2;
            }
            "--font-family" => {
                settings.font_family = args[i+1].clone();
                i += 2;
            }
            "--font-size" => {
                settings.font_size = args[i+1].parse().unwrap_or(14);
                i += 2;
            }
            "--stroke-width" => {
                settings.stroke_width = args[i+1].parse().unwrap_or(2.0);
                i += 2;
            }
            "--scale" => {
                settings.scale = args[i+1].parse().unwrap_or(1.0);
                i += 2;
            }
            "-o" | "--output" => {
                settings.output = Some(args[i+1].clone());
                i += 2;
            }
            "-s" => {
                settings.inline = true;
                i += 1;
            }
            _ => {
                if settings.input.is_none() {
                    settings.input = Some(args[i].clone());
                }
                i += 1;
            }
        }
    }

    let input_text = if settings.inline {
        settings.input.clone().unwrap_or_default()
    } else {
        match settings.input {
            Some(ref filename) => fs::read_to_string(filename).unwrap_or_default(),
            None => {
                let mut buffer = String::new();
                io::stdin().read_to_string(&mut buffer).unwrap_or_default();
                buffer
            }
        }
    };

    let svg = generate_svg(&input_text, &settings);

    match settings.output {
        Some(ref filename) => {
            fs::write(filename, svg).ok();
        }
        None => {
            print!("{}", svg);
        }
    }
}

fn print_help() {
    println!("svgbob 0.7.6\nSvgBobRus is an ascii to svg converter\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFLAGS:\n    -h, --help       Prints help information\n    -s               parse an inline string\n    -V, --version    Prints version information\n\nOPTIONS:\n        --background <background>        backdrop background will be filled with this color (default: 'white')\n        --fill-color <fill-color>        solid shapes will be filled with this color (default: 'black')\n        --font-family <font-family>      text will be rendered with this font (default: 'arial')\n        --font-size <font-size>          text will be rendered with this font size (default: 14)\n    -o, --output <output>                where to write svg output [default: STDOUT]\n        --scale <scale>                  scale the entire svg (dimensions, font size, stroke width) by this factor\n                                         (default: 1)\n        --stroke-color <stroke-color>    stroke color for all lines (default: 'black')\n        --stroke-width <stroke-width>    stroke width for all lines (default: 2)\n\nARGS:\n    <input>    svgbob text file or inline string to parse [default: STDIN]\n\nSUBCOMMANDS:\n    build    Batch convert files to svg.\n    help     Prints this message or the help of the given subcommand(s)");
}

fn handle_build(args: &[String]) {
    let mut input_pattern = String::new();
    let mut outdir = String::new();
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                println!("executable-build 0.0.1\nBatch convert files to svg.\n\nUSAGE:\n    executable build [OPTIONS]\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nOPTIONS:\n    -i, --input <input>      set input file pattern like: *.bob or dir/*.bob\n    -o, --outdir <outdir>    set dir of svg files");
                return;
            }
            "-V" | "--version" => {
                println!("executable-build 0.0.1");
                return;
            }
            "-i" | "--input" => {
                input_pattern = args[i+1].clone();
                i += 2;
            }
            "-o" | "--outdir" => {
                outdir = args[i+1].clone();
                i += 2;
            }
            _ => i += 1,
        }
    }

    let settings = Settings {
        background: "white".to_string(),
        fill_color: "black".to_string(),
        stroke_color: "black".to_string(),
        font_family: "Iosevka Fixed, monospace".to_string(),
        font_size: 14,
        stroke_width: 2.0,
        scale: 1.0,
        inline: false,
        output: None,
        input: None,
    };

    let (dir_path, _file_pattern) = if let Some(pos) = input_pattern.find('*') {
        let prefix = &input_pattern[..pos];
        if prefix.ends_with('/') || prefix.ends_with('\\') {
            (Path::new(&prefix[..prefix.len()-1]), "*.bob")
        } else if prefix.is_empty() {
            (Path::new("."), "*.bob")
        } else {
            (Path::new(prefix), "*.bob")
        }
    } else {
        (Path::new("."), input_pattern.as_str())
    };

    if let Ok(entries) = fs::read_dir(dir_path) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.extension().map_or(false, |ext| ext == "bob") {
                if let Ok(content) = fs::read_to_string(&path) {
                    let svg = generate_svg(&content, &settings);
                    let file_stem = path.file_stem().unwrap().to_str().unwrap();
                    let out_path = Path::new(&outdir).join(format!("{}.svg", file_stem));
                    fs::create_dir_all(&outdir).ok();
                    fs::write(out_path, svg).ok();
                    println!("{} => {}/{}.svg", path.display(), outdir, file_stem);
                }
            }
        }
    }
}

