    if args.len() > 1 && args[1] == "build" {
        handle_build(&args[2..]);
        return;
    }
    if args.len() > 1 && args[1] == "help" {
        print_help();
        return;
    }

    let mut settings = Settings {
        background: "white".to_string(),
        fill_color: "black".to_string(),
        stroke_color: "black".to_string(),
        font_family: "Iosevka Fixed, monospace".to_string(),
        font_size: 14,
        stroke_width: 2.0,
        scale: 1.0,
        inline: false,
        output: None,
        input: None,
    };

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_help();
                return;
            }
            "--version" | "-V" => {
                println!("svgbob 0.7.6");
                return;
            }
            "--background" => {
                settings.background = args[i+1].clone();
                i += 2;
            }
            "--fill-color" => {
                settings.fill_color = args[i+1].clone();
                i += 2;
            }
            "--stroke-color" => {
                settings.stroke_color = args[i+1].clone();
                i += 2;
            }
            "--font-family" => {
                settings.font_family = args[i+1].clone();
                i += 2;
            }
            "--font-size" => {
                settings.font_size = args[i+1].parse().unwrap_or(14);
                i += 2;
            }
            "--stroke-width" => {
                settings.stroke_width = args[i+1].parse().unwrap_or(2.0);
                i += 2;
            }
            "--scale" => {
                settings.scale = args[i+1].parse().unwrap_or(1.0);
                i += 2;
            }
            "-o" | "--output" => {
                settings.output = Some(args[i+1].clone());
                i += 2;
            }
            "-s" => {
                settings.inline = true;
                i += 1;
            }
            _ => {
                if settings.input.is_none() {
                    settings.input = Some(args[i].clone());
                }
                i += 1;
            }
        }
    }

    let input_text = if settings.inline {
        settings.input.clone().unwrap_or_default()
    } else {
        match settings.input {
            Some(ref filename) => fs::read_to_string(filename).unwrap_or_default(),
            None => {
                let mut buffer = String::new();
                io::stdin().read_to_string(&mut buffer).unwrap_or_default();
                buffer
            }
        }
    };

    let svg = generate_svg(&input_text, &settings);

    match settings.output {
        Some(ref filename) => {
            fs::write(filename, svg).ok();
        }
        None => {
            print!("{}", svg);
        }
    }
}

fn print_help() {
    println!("svgbob 0.7.6\nSvgBobRus is an ascii to svg converter\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFLAGS:\n    -h, --help       Prints help information\n    -s               parse an inline string\n    -V, --version    Prints version information\n\nOPTIONS:\n        --background <background>        backdrop background will be filled with this color (default: 'white')\n        --fill-color <fill-color>        solid shapes will be filled with this color (default: 'black')\n        --font-family <font-family>      text will be rendered with this font (default: 'arial')\n        --font-size <font-size>          text will be rendered with this font size (default: 14)\n    -o, --output <output>                where to write svg output [default: STDOUT]\n        --scale <scale>                  scale the entire svg (dimensions, font size, stroke width) by this factor\n                                         (default: 1)\n        --stroke-color <stroke-color>    stroke color for all lines (default: 'black')\n        --stroke-width <stroke-width>    stroke width for all lines (default: 2)\n\nARGS:\n    <input>    svgbob text file or inline string to parse [default: STDIN]\n\nSUBCOMMANDS:\n    build    Batch convert files to svg.\n    help     Prints this message or the help of the given subcommand(s)");
}

fn handle_build(args: &[String]) {
    let mut input_pattern = String::new();
    let mut outdir = String::new();
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                println!("executable-build 0.0.1\nBatch convert files to svg.\n\nUSAGE:\n    executable build [OPTIONS]\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nOPTIONS:\n    -i, --input <input>      set input file pattern like: *.bob or dir/*.bob\n    -o, --outdir <outdir>    set dir of svg files");
                return;
            }
            "-V" | "--version" => {
                println!("executable-build 0.0.1");
                return;
            }
            "-i" | "--input" => {
                input_pattern = args[i+1].clone();
                i += 2;
            }
            "-o" | "--outdir" => {
                outdir = args[i+1].clone();
                i += 2;
            }
            _ => i += 1,
        }
    }

    let settings = Settings {
        background: "white".to_string(),
        fill_color: "black".to_string(),
        stroke_color: "black".to_string(),
        font_family: "Iosevka Fixed, monospace".to_string(),
        font_size: 14,
        stroke_width: 2.0,
        scale: 1.0,
        inline: false,
        output: None,
        input: None,
    };

    let (dir_path, _file_pattern) = if let Some(pos) = input_pattern.find('*') {
        let prefix = &input_pattern[..pos];
        if prefix.ends_with('/') || prefix.ends_with('\\') {
            (Path::new(&prefix[..prefix.len()-1]), "*.bob")
        } else if prefix.is_empty() {
            (Path::new("."), "*.bob")
        } else {
            (Path::new(prefix), "*.bob")
        }
    } else {
        (Path::new("."), input_pattern.as_str())
    };

    if let Ok(entries) = fs::read_dir(dir_path) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.extension().map_or(false, |ext| ext == "bob") {
                if let Ok(content) = fs::read_to_string(&path) {
                    let svg = generate_svg(&content, &settings);
                    let file_stem = path.file_stem().unwrap().to_str().unwrap();
                    let out_path = Path::new(&outdir).join(format!("{}.svg", file_stem));
                    fs::create_dir_all(&outdir).ok();
                    fs::write(out_path, svg).ok();
                    println!("{} => {}/{}.svg", path.display(), outdir, file_stem);
                }
            }
        }
    }
}

fn generate_svg(text: &str, settings: &Settings) -> String {
    let lines_str: Vec<&str> = text.lines().collect();
    let lines: Vec<Vec<char>> = lines_str.iter().map(|l| l.chars().collect()).collect();
    let mut max_cols = 0;
    for line in &lines {
        max_cols = max_cols.max(line.len());
    }
    let max_rows = lines.len();

    let max_col_idx = if max_cols > 0 { max_cols - 1 } else { 0 };
    let max_row_idx = if max_rows > 0 { max_rows - 1 } else { 0 };
    let svg_width = ((max_col_idx as f32 + 2.0) * 8.0 * settings.scale) as u32;
    let svg_height = ((max_row_idx as f32 + 2.0) * 16.0 * settings.scale) as u32;

    let mut elements = String::new();
    elements.push_str(&format!(r#"  <rect class="backdrop" x="0" y="0" width="{}" height="{}"></rect>
"#, svg_width, svg_height));

    let mut used = vec![vec![false; max_cols]; max_rows];

    for r in 0..max_rows {
        for c in 0..lines[r].len() {
            let ch = lines[r][c];
            let x = (c as f32 * 8.0 + 4.0) * settings.scale;
            let y = (r as f32 * 16.0 + 8.0) * settings.scale;
            let sc = settings.scale;

            match ch {
                '-' => {
                    elements.push_str(&format!(r#"  <line x1="{}" y1="{}" x2="{}" y2="{}" class="solid"></line>
"#, (c as f32 * 8.0) * sc, y, (c as f32 * 8.0 + 8.0) * sc, y));
                    used[r][c] = true;
                }
                '|' => {
                    elements.push_str(&format!(r#"  <line x1="{}" y1="{}" x2="{}" y2="{}" class="solid"></line>
"#, x, (r as f32 * 16.0) * sc, x, (r as f32 * 16.0 + 16.0) * sc));
                    used[r][c] = true;
                }
                '_' => {
                    elements.push_str(&format!(r#"  <line x1="{}" y1="{}" x2="{}" y2="{}" class="solid"></line>
"#, (c as f32 * 8.0) * sc, (r as f32 * 16.0 + 16.0) * sc, (c as f32 * 8.0 + 8.0) * sc, (r as f32 * 16.0 + 16.0) * sc));
                    used[r][c] = true;
                }
                '/' => {
                    elements.push_str(&format!(r#"  <line x1="{}" y1="{}" x2="{}" y2="{}" class="solid"></line>
"#, (c as f32 * 8.0 + 8.0) * sc, (r as f32 * 16.0) * sc, (c as f32 * 8.0) * sc, (r as f32 * 16.0 + 16.0) * sc));
                    used[r][c] = true;
                }
                '\\' => {
                    elements.push_str(&format!(r#"  <line x1="{}" y1="{}" x2="{}" y2="{}" class="solid"></line>
"#, (c as f32 * 8.0) * sc, (r as f32 * 16.0) * sc, (c as f32 * 8.0 + 8.0) * sc, (r as f32 * 16.0 + 16.0) * sc));
                    used[r][c] = true;
                }
                '+' => {
                    if c > 0 && c - 1 < lines[r].len() && (lines[r][c-1] == '-' || lines[r][c-1] == '+') {
                        elements.push_str(&format!(r#"  <line x1="{}" y1="{}" x2="{}" y2="{}" class="solid"></line>
"#, x - 4.0 * sc, y, x, y));
                    }
                    if c + 1 < lines[r].len() && (lines[r][c+1] == '-' || lines[r][c+1] == '+') {
                        elements.push_str(&format!(r#"  <line x1="{}" y1="{}" x2="{}" y2="{}" class="solid"></line>
"#, x, y, x + 4.0 * sc, y));
                    }
                    if r > 0 && c < lines[r-1].len() && (lines[r-1][c] == '|' || lines[r-1][c] == '+') {
                        elements.push_str(&format!(r#"  <line x1="{}" y1="{}" x2="{}" y2="{}" class="solid"></line>
"#, x, y - 8.0 * sc, x, y));
                    }
                    if r + 1 < lines.len() && c < lines[r+1].len() && (lines[r+1][c] == '|' || lines[r+1][c] == '+') {
                        elements.push_str(&format!(r#"  <line x1="{}" y1="{}" x2="{}" y2="{}" class="solid"></line>
"#, x, y, x, y + 8.0 * sc));
                    }
                    used[r][c] = true;
                }
                '>' => {
                    elements.push_str(&format!(r#"  <polygon points="{},{} {},{} {},{}" class="filled"></polygon>
"#, x - 4.0 * sc, y - 4.0 * sc, x + 4.0 * sc, y, x - 4.0 * sc, y + 4.0 * sc));
                    used[r][c] = true;
                }
                <' => {
                    elements.push_str(&format!(r#"  <polygon points="{},{} {},{} {},{}" class="filled"></polygon>
"#, x + 4.0 * sc, y - 4.0 * sc, x - 4.0 * sc, y, x + 4.0 * sc, y + 4.0 * sc));
                    used[r][c] = true;
                }
                '^' => {
                    elements.push_str(&format!(r#"  <polygon points="{},{} {},{} {},{}" class="filled"></polygon>
"#, x - 4.0 * sc, y + 4.0 * sc, x, y - 8.0 * sc, x + 4.0 * sc, y + 4.0 * sc));
                    used[r][c] = true;
                }
                'v' => {
                    elements.push_str(&format!(r#"  <polygon points="{},{} {},{} {},{}" class="filled"></polygon>
"#, x - 4.0 * sc, y - 4.0 * sc, x + 4.0 * sc, y - 4.0 * sc, x, y + 8.0 * sc));
                    used[r][c] = true;
                }
                _ => {}
            }
        }
    }

    for r in 0..max_rows {
        let mut c = 0;
        while c < lines[r].len() {
            if !used[r][c] && lines[r][c] != ' ' {
                let start_c = c;
                let mut text_str = String::new();
                while c < lines[r].len() && !used[r][c] && lines[r][c] != ' ' {
                    text_str.push(lines[r][c]);
                    c += 1;
                }
                if !text_str.is_empty() {
                    let tx = (start_c as f32 * 8.0 + 2.0) * settings.scale;
                    let ty = (r as f32 * 16.0 + 12.0) * settings.scale;
                    elements.push_str(&format!(r#"  <text x="{}" y="{}" >{}</text>
"#, tx, ty, text_str));
                }
            } else {
                c += 1;
            }
        }
    }

    format!(r#"<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" class="svgbob">
  <style>.svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon {{
  stroke: {stroke_color};
  stroke-width: {stroke_width};
  stroke-opacity: 1;
  fill-opacity: 1;
  stroke-linecap: round;
  stroke-linejoin: miter;
}}

.svgbob text {{
  white-space: pre;
  fill: {fill_color};
  font-family: {font_family};
  font-size: {font_size}px;
}}

.svgbob rect.backdrop {{
  stroke: none;
  fill: {background};
}}

.svgbob .broken {{
  stroke-dasharray: 8;
}}

.svgbob .filled {{
  fill: {fill_color};
}}

.svgbob .bg_filled {{
  fill: {background};
  stroke-width: 1;
}}

.svgbob .nofill {{
  fill: {background};
}}

.svgbob .end_marked_arrow {{
  marker-end: url(#arrow);
}}

.svgbob .start_marked_arrow {{
  marker-start: url(#arrow);
}}

.svgbob .end_marked_diamond {{
  marker-end: url(#diamond);
}}

.svgbob .start_marked_diamond {{
  marker-start: url(#diamond);
}}

.svgbob .end_marked_circle {{
  marker-end: url(#circle);
}}

.svgbob .start_marked_circle {{
  marker-start: url(#circle);
}}

.svgbob .end_marked_open_circle {{
  marker-end: url(#open_circle);
}}

.svgbob .start_marked_open_circle {{
  marker-start: url(#open_circle);
}}

.svgbob .end_marked_big_open_circle {{
  marker-end: url(#big_open_circle);
}}

.svgbob .start_marked_big_open_circle {{
  marker-start: url(#big_open_circle);
}}

</style>
  <defs>
    <marker id="arrow" viewBox="-2 -2 8 8" refX="4" refY="2" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <polygon points="0,0 0,4 4,2 0,0"></polygon>
    </marker>
    <marker id="diamond" viewBox="-2 -2 8 8" refX="4" refY="2" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <polygon points="0,2 2,0 4,2 2,4 0,2"></polygon>
    </marker>
    <marker id="circle" viewBox="0 0 8 8" refX="4" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <circle cx="4" cy="4" r="2" class="filled"></circle>
    </marker>
    <marker id="open_circle" viewBox="0 0 8 8" refX="4" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <circle cx="4" cy="4" r="2" class="bg_filled"></circle>
    </marker>
    <marker id="big_open_circle" viewBox="0 0 8 8" refX="4" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <circle cx="4" cy="4" r="3" class="bg_filled"></circle>
    </marker>
  </defs>
{elements}</svg>"#, 
    width=svg_width,
    height=svg_height,
    stroke_color=settings.stroke_color,
    stroke_width=settings.stroke_width,
    fill_color=settings.fill_color,
    font_family=settings.font_family,
    font_size=settings.font_size,
    background=settings.background,
    elements=elements)
}
EOF
./compile.sh
